// 全局前置守卫 - 核心逻辑：
// 1. 强制同步URL前缀与本地country
// 2. / 跳 /Country，/xx 跳 /xx/home（并刷新页面）
router.beforeEach((to, from, next) => {
  // Google OAuth callback: save code before redirects strip it
  // Google OAuth callback: if URL has code param, let App.vue handle it — do NOT redirect
  const urlSearch = new URLSearchParams(window.location.search)
  const rawCode = to.query.code || urlSearch.get('code')
  if (rawCode) {
    console.log('[Google OAuth] Router guard: Google callback detected, letting App.vue handle it')
    return next()
  }

  const savedCountry = localStorage.getItem('country') // 本地存储的前缀
  const routePrefix = to.params.prefix // URL中的前缀
  let finalPrefix = ''

  // 1. 前缀同步逻辑（保持原有规则）
  if (savedCountry) {
    finalPrefix = savedCountry
    // 如果URL前缀和本地不一致，强制重定向到本地前缀的URL
    if (routePrefix !== savedCountry) {
      const pathWithoutPrefix = to.path.replace(/^\/[^/]+/, '') || ''
      const correctPath = `/${savedCountry}${pathWithoutPrefix}`
      // Google OAuth callback: use full page reload so App.vue re-mounts and processes the code
      if (localStorage.getItem('googleAuthCode')) {
        window.location.href = correctPath
        return
      }
      return next(correctPath)
    }
  } else {
    // 本地无值：用URL前缀并存储到本地
    finalPrefix = routePrefix || ''
    if (finalPrefix) {
      localStorage.setItem('country', finalPrefix)
    }
  }

  // 2. 核心重定向规则：/ 跳 /Country，/xx 跳 /xx/home（带刷新）
  // 分割路径并过滤空值，得到有效路径段数组
  const pathSegments = to.path.split('/').filter(Boolean)

  // 已定义的合法子路由列表（避免对已定义路由重复重定向）
  const validSubPaths = [
    'Crowdfunding',
    'Country',
    'home',
    'menu',
    'Support',
    'bonus',
    'lottery',
    'share',
    'mine',
    'activity'
  ]

  // 场景1：访问纯根路径 / → 跳 /Country
  if (pathSegments.length === 0) {
    // Google OAuth callback at root: need full reload for App.vue to process code
    if (localStorage.getItem('googleAuthCode') && savedCountry) {
      window.location.href = `/${savedCountry}/home`
      return
    }
    return next('/Country')
  }
  // 场景2：访问纯前缀路径 /xx（无任何子路径）→ 跳 /xx/home 并刷新页面
  else if (
    pathSegments.length === 1 &&
    !validSubPaths.includes(pathSegments[0])
  ) {
    const prefix = pathSegments[0]
    // 存储前缀到本地
    localStorage.setItem('country', prefix)
    const targetPath = `/${prefix}/home`
    // 关键修改：使用window.location.href触发页面刷新，而非next()
    window.location.href = targetPath
    // 终止后续逻辑执行
    return
  }

  // 3. 原有权限验证逻辑（保持不变）
  const needAuthPaths = ['/rechargeCont', '/mine', '/share']
  const currentPath = to.path.replace(/^\/[^/]+/, '') || '/'

  if (needAuthPaths.includes(currentPath)) {
    const token = localStorage.getItem('token')
    if (!token) {
      const redirectPath = finalPrefix ? `/${finalPrefix}/home` : '/home'
      if (!from.fullPath) {
        next(redirectPath)
      } else {
        setTimeout(() => {
          next(redirectPath)
        }, 0)
      }
      return
    }
  }

  // 合法路由直接放行
  next()
})

export default router
