// 扩展 Vue 原型，添加支持 push/replace 的跳转方法
Vue.prototype.$jumpTo = function (routeName, params = {}, options = {}) {
  // 获取本地存储的前缀
  const prefix = localStorage.getItem('country') || ''
  // 合并前缀参数和业务参数
  const finalParams = {
    ...params
  }

  // 构建跳转配置
  const routeConfig = {
    path: '/' + prefix + routeName,
    query: finalParams
  }

  // 根据配置选择跳转方式：默认 push，可通过 replace: true 指定 replace
  const jumpMethod = options.replace ? 'replace' : 'push'

  // 执行跳转（增加异常捕获，避免重复跳转同一路由报错）
  try {
    this.$router[jumpMethod](routeConfig)
  } catch (error) {
    // 静默处理重复跳转的错误（也可根据需要添加日志）
    if (
      !error.message.includes(
        'Avoided redundant navigation to current location'
      )
    ) {
      console.error(error)
    }
  }
}

// 直接启动游戏（跳过 gameDetail 页，点击即进）
Vue.prototype.$launchGame = function (jumpPayload) {
  if (!jumpPayload) return
  if (jumpPayload.type === 'lottery') {
    this.$jumpTo('/lotteryDetail', {
      lotteryType: jumpPayload.lotteryType,
      lotteryName: jumpPayload.lotteryName,
      typeCate: jumpPayload.typeCate != null ? jumpPayload.typeCate : 1
    })
    return
  }
  const prefix = localStorage.getItem('country') || ''
  this.$router.push({
    name: 'GameHall',
    params: {
      prefix,
      gid: jumpPayload.gid,
      isDemo: jumpPayload.isDemo != null ? jumpPayload.isDemo : 0,
      from: jumpPayload.from || 'game',
      typeCate: jumpPayload.typeCate,
      gameTab: jumpPayload.gameTab
    }
  })
  localStorage.setItem('hallFrome', 'game')
  localStorage.setItem('hallGid', String(jumpPayload.gid))
}

